// ArtiSys snapshot: utilidades@4a138a9d77775f5be1e43244b9d45ca8586742c5 / artisys-exporter 0.1.0
const quote=(value,delimiter)=>{const s=value==null?'':String(value);return s.includes(delimiter)||/["\r\n]/.test(s)?`"${s.replaceAll('"','""')}"`:s};
export function normalizeColumns(rows=[],columns=null){if(columns?.length)return columns.map(c=>typeof c==='string'?{key:c,label:c}:c);const keys=[];for(const row of rows)for(const key of Object.keys(row??{}))if(!keys.includes(key))keys.push(key);return keys.map(key=>({key,label:key}))}
export function toCsv(rows=[],{columns=null,delimiter=',',bom=false}={}){if(typeof delimiter!=='string'||delimiter.length!==1)throw new TypeError('CSV delimiter must be one character');const cols=normalizeColumns(rows,columns);const lines=[cols.map(c=>quote(c.label??c.key,delimiter)).join(delimiter),...rows.map(row=>cols.map(c=>quote(row?.[c.key],delimiter)).join(delimiter))];return (bom?'\ufeff':'')+lines.join('\r\n')}
export function toJson(rows=[],{pretty=false}={}){return JSON.stringify(rows,null,pretty?2:0)}
export function toWorkbookModel(rows=[],{columns=null,sheetName='Dados'}={}){const cols=normalizeColumns(rows,columns);return Object.freeze({sheetName:String(sheetName),columns:Object.freeze(cols.map(c=>Object.freeze({...c}))),rows:Object.freeze(rows.map(row=>Object.freeze(cols.map(c=>row?.[c.key]??null))))})}
export function exportRows(rows=[],{format='csv',...options}={}){if(format==='csv')return toCsv(rows,options);if(format==='json')return toJson(rows,options);if(format==='xlsx-model')return toWorkbookModel(rows,options);throw new TypeError(`unsupported export format: ${format}`)}
